import fs from "fs"
import os from "os"
import path from "path"
import { parse } from "yaml"
import { describe, expect, test } from "vitest"
import {
  getOrgOptions,
  NEW_ORG_OPTION,
  orgIdFromOption,
  orgOptionLabel,
  outdatedIssueTemplates,
  renderIssueTemplate,
} from "./IssueTemplate"

const TEMPLATE = `body:
  - type: dropdown
    id: org-id
    attributes:
      options:
        # BEGIN org options (generated by \`npm run update-issue-template\`, don't edit by hand)
        - "stale option"
        # END org options
`

function makeOrgsDir(orgs: Record<string, string>): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "orgs-"))
  for (const [id, frontmatter] of Object.entries(orgs)) {
    fs.mkdirSync(path.join(dir, id))
    fs.writeFileSync(path.join(dir, id, "index.md"), `---\n${frontmatter}\n---\n\nAbout\n`)
  }
  fs.mkdirSync(path.join(dir, "empty_folder"))
  return dir
}

describe("getOrgOptions", () => {
  test("reads titles (quoted or not, CRLF too) and sorts by title", () => {
    const dir = makeOrgsDir({
      zeta: 'title: "Zeta Group"',
      taqelah: "title: TAQELAH Singapore",
      aws: 'title: "AWS User Group Singapore"\r\ndescription: x',
      untitled: "description: no title",
    })
    expect(getOrgOptions(dir)).toEqual([
      { id: "aws", title: "AWS User Group Singapore" },
      { id: "taqelah", title: "TAQELAH Singapore" },
      { id: "untitled", title: "untitled" },
      { id: "zeta", title: "Zeta Group" },
    ])
  })
})

describe("renderIssueTemplate", () => {
  test("replaces the options between the markers and keeps the new-org option last", () => {
    const orgs = [
      { id: "div0", title: "Division Zero (Div0): Cybersecurity" },
      { id: "quoted", title: 'The "Best" Meetup' },
    ]
    const rendered = renderIssueTemplate(TEMPLATE, orgs)

    expect(rendered).not.toContain("stale option")
    expect(parse(rendered).body[0].attributes.options).toEqual([
      "Division Zero (Div0): Cybersecurity (div0)",
      'The "Best" Meetup (quoted)',
      NEW_ORG_OPTION,
    ])
    expect(renderIssueTemplate(rendered, orgs)).toBe(rendered)
  })

  test("fails loudly without the markers", () => {
    expect(() => renderIssueTemplate("body: []\n", [])).toThrow("markers not found")
  })
})

describe("orgIdFromOption", () => {
  test("reads the ID back from an option, even when the title has parentheses", () => {
    expect(orgIdFromOption(orgOptionLabel({ id: "division_zero_div0", title: "Division Zero (Div0)" }))).toBe(
      "division_zero_div0",
    )
    expect(orgIdFromOption(NEW_ORG_OPTION)).toBeNull()
    expect(orgIdFromOption("Something else")).toBeNull()
  })
})

describe("the event submission issue forms", () => {
  test("list every org in src/content/orgs (run `npm run update-issue-template` if this fails)", () => {
    expect(outdatedIssueTemplates()).toEqual([])
  })
})
